# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, factor=2):
    return [v * factor for v in xs[1:]]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(shape(sift(render(raw))))

